/**
 * apiRoutes.ts
 *
 * THE CLIENT-SIDE VIEW OF THE BACKEND ENDPOINTS.
 *
 * WHY THIS FILE EXISTS
 * The real backend paths must not appear in the client bundle: anybody who
 * opens the DevTools could read them and call the backend directly,
 * bypassing the frontend entirely.
 *
 * So the frontend only knows an OPAQUE TOKEN per endpoint. The real path
 * lives in the server-only environment variable `API_ROUTE_MAP` and is
 * resolved by the proxy in `src/pages/api/backend/[...segments].ts`.
 *
 * The tokens below are generated by `scripts/sync-api-routes.mjs` from
 * `scripts/api-routes.table.mjs`. Run `npm run routes:sync` after editing
 * the table.
 *
 * This file is generated — do not edit it by hand.
 */

import { getApiBaseUrl } from './apiBase';

