/** The name of an endpoint. */
export type ApiRouteKey = keyof typeof RT;

/**
 * Reads the server-only route map.
 *
 * The variable is read with the BRACKET notation on purpose: Next.js only
 * inlines the `process.env.SOMETHING` form, so the bracket form keeps the
 * value out of the client bundle.
 *
 * @returns The map, or an empty object when it is unavailable.
 */
const readServerRouteMap = (): Record<string, string> => {
  const raw = process.env['API_ROUTE_MAP'];
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== 'object') return {};
    return parsed as Record<string, string>;
  } catch {
    return {};
  }
};

/**
 * Substitutes the path parameters into a route template.
 *
 * @param template - The template, for example `/movies/{0}`.
 * @param params - The parameter values, in order.
 * @returns The path, and the number of consumed parameters.
 */
const applyParams = (
  template: string,
  params: (string | number | undefined)[]
): { path: string; consumed: number } => {
  let consumed = 0;
  const path = template.replace(/\{(\d+)\}/g, (match) => {
    const value = params[consumed];
    consumed += 1;
    return value === undefined ? match : encodeURIComponent(String(value));
  });
  return { path, consumed };
};

/**
 * Builds the RELATIVE path of an endpoint.
 *
 * The result is relative on purpose, so the SAME call site works in both
 * runtimes:
 *   - in the browser: `tf65666fc/param` — joined with the base
 *     `/api/backend`, so the request goes to the proxy, which resolves the
 *     token into the real path on the server;
 *   - on the server: `/movies/param` — joined with the real backend base,
 *     so the server calls the backend directly without any extra hop.
 *
 * @param key - The endpoint name.
 * @param params - The path parameters, in order.
 * @returns The relative path of the endpoint.
 */
export const apiRoute = (
  key: ApiRouteKey,
  ...params: (string | number | undefined)[]
): string => {
  const token = RT[key];

  // The browser: the opaque token. The real path is unknown here, and that
  // is exactly the point.
  if (typeof window !== 'undefined') {
    const suffix = params
      .filter((value) => value !== undefined && value !== null)
      .map((value) => encodeURIComponent(String(value)))
      .join('/');
    return suffix ? `${token}/${suffix}` : token;
  }

  // The server: the real path, read from the server-only map.
  const template = readServerRouteMap()[token];
  if (!template) return '';
  const { path, consumed } = applyParams(template, params);
  const extra = params
    .slice(consumed)
    .filter((value) => value !== undefined && value !== null)
    .map((value) => encodeURIComponent(String(value)));
  return extra.length ? `${path}/${extra.join('/')}` : path;
};

/**
 * Builds the FULL URL of an endpoint.
 *
 * It joins the relative path of `apiRoute()` with the base URL of the
 * current runtime, so it works for a plain `fetch()` in both runtimes.
 *
 * @param key - The endpoint name.
 * @param params - The path parameters, in order.
 * @returns The full URL of the endpoint.
 */
export const apiUrl = (
  key: ApiRouteKey,
  ...params: (string | number | undefined)[]
): string => {
  const base = getApiBaseUrl();
  const path = apiRoute(key, ...params);
  if (!path) return base;
  return `${base.replace(/\/+$/, '')}/${path.replace(/^\/+/, '')}`;
};

/**
 * Appends a query string to a URL.
 *
 * @param url - The URL.
 * @param params - The query parameters. Empty values are skipped.
 * @returns The URL with an encoded query string.
 */
export const withQuery = (
  url: string,
  params?: Record<string, string | number | undefined | null>
): string => {
  if (!params) return url;
  const query = Object.entries(params)
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join('&');
  return query ? `${url}?${query}` : url;
};

export default apiRoute;
